.jui-command-search,.jui-command-search-panel{--cs-bg:#f5f4f3;--cs-text:#171717;--cs-muted:#858585;--cs-border:#dedddc;--cs-selected:#e1e0df;color:var(--cs-text);font:14px/1.4 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
.jui-command-search[data-theme=dark],.jui-command-search-panel[data-theme=dark]{--cs-bg:#191919;--cs-text:#ededed;--cs-muted:#8d8d8d;--cs-border:#333;--cs-selected:#303030;color-scheme:dark}
.jui-command-search{width:192px;max-width:100%;height:32px}
.jui-command-search-trigger{position:relative;display:flex;align-items:center;gap:8px;width:100%;height:32px;padding:4px 6px 4px 8px;border:1px solid var(--cs-border);border-radius:6px;background:var(--cs-bg);color:var(--cs-muted);font:inherit;text-align:left;cursor:pointer}
.jui-command-search-trigger-row{position:relative;display:flex;align-items:center;gap:8px;width:100%}.jui-command-search-trigger-row>span{flex:1}.jui-command-search kbd,.jui-command-search-panel kbd{display:inline-block;padding:1px 4px;border:1px solid var(--cs-border);border-radius:3px;color:var(--cs-text);font-family:inherit;font-size:11px;line-height:18px;box-shadow:0 1px 2px #0001}
.jui-command-search-trigger:focus-visible{outline:none;border-radius:6px;box-shadow:0 0 0 1px var(--cs-border)}
.jui-command-search-panel{z-index:1100;box-sizing:border-box;width:min(var(--cs-width),calc(100vw - 24px));border:1px solid var(--cs-border);border-radius:12px;background:var(--cs-bg);outline:none;overflow:hidden;box-shadow:0 1px 5px #00000008}
.jui-command-search-panel *{box-sizing:border-box}
.jui-command-search-field{display:flex;align-items:center;gap:12px;height:48px;padding:0 12px 0 16px;border-bottom:1px solid var(--cs-border)}
.jui-command-search-field input{width:0;min-width:0;flex:1;border:0;outline:none!important;box-shadow:none;background:none;color:var(--cs-text);font:inherit;height:40px;padding:0}
.jui-command-search-field input::placeholder{color:var(--cs-muted)}
.jui-command-search-escape{padding:0;border:0;background:none;color:var(--cs-text);cursor:pointer}.jui-command-search-escape:focus-visible{outline:1px solid var(--cs-muted);outline-offset:3px}
.jui-command-search-list{height:var(--cs-list-height,300px);min-height:96px;overflow-y:auto;overscroll-behavior:contain;scroll-padding:8px;scrollbar-width:thin}
.jui-command-search-panel [cmdk-group]{padding:4px}.jui-command-search-panel [cmdk-group][hidden]{display:none}
.jui-command-search-panel [cmdk-group]+[cmdk-group]{border-top:1px solid var(--cs-border)}
.jui-command-search-panel [cmdk-group-heading]{padding:6px 8px;font-size:12px;color:var(--cs-muted)}
.jui-command-search-panel [cmdk-item]{display:flex;align-items:center;gap:10px;height:32px;padding:0 8px;border-radius:5px;cursor:pointer;outline:none;user-select:none}
.jui-command-search-panel [cmdk-item][data-selected=true]{background:var(--cs-selected)}
.jui-command-search-panel [cmdk-item][data-disabled=true]{opacity:.4;pointer-events:none}
.jui-command-search-icon{display:grid;place-items:center;width:16px;height:16px;flex:none}.jui-command-search-icon svg{width:16px;height:16px}
.jui-command-search-hint{margin-left:auto;color:var(--cs-muted);font-size:12px}.jui-command-search-empty{padding:28px 16px;text-align:center;color:var(--cs-muted);font-size:13px}

/* Shared-layout geometry matches the reference: 32px cells become 48px. */
.jui-command-search-layer{position:fixed;inset:0;z-index:1100;pointer-events:none;--cs-bg:#f5f4f3}
.jui-command-search-layer[data-theme=dark]{--cs-bg:#191919}
.jui-command-search-backdrop{position:absolute;inset:0;pointer-events:auto;background:color-mix(in srgb,var(--cs-bg) 80%,transparent)}
.jui-command-search-trigger{padding:0;gap:0;border:0;background:transparent;color:var(--cs-text)}
.jui-command-search-border{position:absolute;inset:0;border:1px solid var(--cs-border);pointer-events:none;transform-origin:top left}
.jui-command-search-trigger:hover .jui-command-search-border{border-color:color-mix(in srgb,var(--cs-text) 20%,transparent)}
.jui-command-search-icon-cell,.jui-command-search-key{display:flex;flex:none;align-items:center;justify-content:center;width:32px;height:32px}
.jui-command-search-icon-cell>span{display:flex}
.jui-command-search-trigger .jui-command-search-icon-cell{opacity:.5}
.jui-command-search-placeholder{position:relative;flex:1;opacity:.4}
.jui-command-search-placeholder>span{position:absolute;display:grid;align-items:center;top:-16px;width:286px;height:32px}
.jui-command-search kbd,.jui-command-search-panel kbd{font-size:12px;line-height:16px;box-shadow:none}
.jui-command-search-trigger kbd{display:grid;place-items:center;width:22px;height:22px;padding:0}
.jui-command-search-panel{position:absolute;pointer-events:auto;border:0;overflow:visible;background:var(--cs-bg);box-shadow:0 4px 6px -1px #0000001a,0 2px 4px -2px #0000001a}
.jui-command-search-panel>.jui-command-search-border{inset:-1px}
.jui-command-search-panel [cmdk-root]{border-radius:8px;overflow:hidden}
.jui-command-search-field{position:relative;padding:0;gap:0;height:49px}
.jui-command-search-field .jui-command-search-icon-cell,.jui-command-search-field .jui-command-search-key{width:48px;height:48px}
.jui-command-search-field .jui-command-search-key{padding-right:4px}
.jui-command-search-field kbd{padding:2px 4px;letter-spacing:-.6px}
.jui-command-search-input{display:flex;align-items:center;flex:1;min-width:0;height:100%}
.jui-command-search-field input{width:100%;height:40px}
.jui-command-search-results{position:relative;overflow:hidden}
.jui-command-search-list{height:auto;min-height:0;max-height:var(--cs-list-height,300px);scroll-padding:4px;mask-image:linear-gradient(to bottom,transparent,#000 8px,#000 calc(100% - 8px),transparent)}
.jui-command-search-panel [cmdk-item]{gap:8px;cursor:default;border-radius:4px;padding:6px 8px}
.jui-command-search-icon{color:var(--cs-muted)}
.jui-command-search-hint{letter-spacing:1.2px}
.jui-command-search-empty{padding:24px 0;font-size:14px}
.jui-command-search-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

"use client";
import { useEffect, useLayoutEffect, useId, useRef, useState, type ComponentProps, type ReactNode, type CSSProperties } from "react";
import * as Dialog from "@radix-ui/react-dialog";
import { Command } from "cmdk";
import { AnimatePresence, LayoutGroup, MotionConfig, motion, useReducedMotion } from "motion/react";
import { ArrowRight, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import "./command-search.css";

// Independent implementation. Visual reference: Skiper UI's Vercel Command Search.
export type CommandSearchItem = {
  id: string;
  label: string;
  group?: string;
  keywords?: string[];
  icon?: ReactNode;
  hint?: string;
  disabled?: boolean;
};
export type CommandSearchProps = Omit<ComponentProps<"div">, "children" | "onSelect"> & {
  items: CommandSearchItem[];
  onSelect?: (item: CommandSearchItem) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  placeholder?: string;
  label?: string;
  emptyLabel?: string;
  shortcut?: string | false;
  theme?: "light" | "dark";
  width?: number;
};
export function CommandSearch({ items, onSelect, open: controlledOpen, defaultOpen = false, onOpenChange, placeholder = "Find...", label = "Command search", emptyLabel = "No results found.", shortcut = "f", theme = "light", width = 384, className, ...props }: CommandSearchProps) {
  const id = useId();
  const reduced = useReducedMotion();
  const anchor = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const [query, setQuery] = useState("");
  const [placement, setPlacement] = useState({ left: 0, top: 0, listHeight: 300 });
  const open = controlledOpen ?? internalOpen;
  const changeOpen = (next: boolean) => {
    if (controlledOpen === undefined) setInternalOpen(next);
    if (next) setQuery("");
    onOpenChange?.(next);
  };
  useEffect(() => {
    if (!shortcut || open) return;
    const handleKey = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.repeat || event.isComposing || event.metaKey || event.ctrlKey || event.altKey || event.key.toLowerCase() !== shortcut.toLowerCase()) return;
      if (event.target instanceof HTMLElement && (event.target.isContentEditable || event.target.closest("input,textarea,select,[role='textbox']"))) return;
      const rect = trigger.current?.getBoundingClientRect();
      if (!rect || !rect.width || rect.bottom < 0 || rect.top > window.innerHeight) return;
      event.preventDefault();
      if (controlledOpen === undefined) setInternalOpen(true);
      setQuery("");
      onOpenChange?.(true);
    };
    document.addEventListener("keydown", handleKey);
    return () => document.removeEventListener("keydown", handleKey);
  }, [shortcut, open, controlledOpen, onOpenChange]);
  useLayoutEffect(() => {
    if (!open) return;
    const measure = () => {
      const rect = anchor.current?.getBoundingClientRect();
      if (!rect) return;
      const panelWidth = Math.min(Math.max(240, width), window.innerWidth - 24);
      const top = Math.max(12, Math.min(rect.top - 8, window.innerHeight - 156));
      setPlacement({ left: Math.max(12, Math.min(rect.left - 16, window.innerWidth - 12 - panelWidth)), top, listHeight: Math.min(300, window.innerHeight - top - 60) });
    };
    measure();
    window.addEventListener("resize", measure);
    window.addEventListener("scroll", measure, true);
    return () => { window.removeEventListener("resize", measure); window.removeEventListener("scroll", measure, true); };
  }, [open, width]);
  const groups = Array.from(new Set(items.map((item) => item.group ?? "")));
  // Verified from the public Skiper92 bundle: shared wrapper/icon/center/key,
  // a low-mass spring, and a separately entering list. Anchor measurements must
  // come from the static root, never the button undergoing layout projection.
  const transition = reduced ? { duration: 0 } : { type: "spring" as const, stiffness: 450, damping: 25, mass: 0.1 };
  return <LayoutGroup id={id}><MotionConfig transition={transition}><Dialog.Root open={open} onOpenChange={changeOpen}>
    <div {...props} ref={anchor} data-slot="command-search" data-theme={theme} className={cn("jui-command-search", className)}>
      <Dialog.Trigger asChild><motion.button layoutId="wrapper" ref={trigger} type="button" className="jui-command-search-trigger" aria-label={label}>
        <motion.span layoutId="border" className="jui-command-search-border" style={{ borderRadius: 6 }}/>
        <span className="jui-command-search-icon-cell"><motion.span layoutId="icon"><Search size={16} aria-hidden="true"/></motion.span></span>
        <span className="jui-command-search-placeholder"><motion.span layoutId="center">{placeholder}</motion.span></span>
        <motion.span layoutId="wordwrapper" transition={{ duration: reduced ? 0 : 0.1 }} className="jui-command-search-key">{shortcut && <kbd>{shortcut.toUpperCase()}</kbd>}</motion.span>
      </motion.button></Dialog.Trigger>
    </div>
    <AnimatePresence>{open && <Dialog.Portal forceMount>
      <motion.div layoutRoot className="jui-command-search-layer" data-theme={theme}>
        <Dialog.Overlay forceMount className="jui-command-search-backdrop"/>
        <Dialog.Content forceMount asChild aria-describedby={undefined} onOpenAutoFocus={(event) => { event.preventDefault(); input.current?.focus({ preventScroll: true }); }} onCloseAutoFocus={(event) => { event.preventDefault(); trigger.current?.focus({ preventScroll: true }); }}>
          <motion.div layoutId="wrapper" data-slot="command-search-panel" data-theme={theme} className="jui-command-search-panel" style={{ left: placement.left, top: placement.top, "--cs-width": `${Math.max(240, width)}px`, "--cs-list-height": `${placement.listHeight}px`, borderRadius: 12 } as CSSProperties}>
            <Dialog.Title className="jui-command-search-sr-only">{label}</Dialog.Title>
            <span className="jui-command-search-border" style={{ borderRadius: 12 }}/>
            <Command label={label}>
              <div className="jui-command-search-field">
                <span className="jui-command-search-icon-cell"><motion.span layoutId="icon"><Search size={16} aria-hidden="true"/></motion.span></span>
                <motion.span layoutId="center" className="jui-command-search-input"><Command.Input ref={input} value={query} onValueChange={setQuery} placeholder={placeholder} aria-label={label}/></motion.span>
                <motion.span layoutId="wordwrapper" className="jui-command-search-key"><kbd>Esc</kbd></motion.span>
              </div>
              <motion.div className="jui-command-search-results" initial={{ opacity: reduced ? 1 : 0, y: reduced ? 0 : -50 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: reduced ? 1 : 0, y: reduced ? 0 : -50 }}>
                <Command.List className="jui-command-search-list">
                  <Command.Empty className="jui-command-search-empty">{emptyLabel}</Command.Empty>
                  {groups.map((group) => <Command.Group key={group} heading={group || undefined}>
                    {items.filter((item) => (item.group ?? "") === group).map((item) => <Command.Item key={item.id} value={item.id} keywords={[item.label, ...(item.keywords ?? [])]} disabled={item.disabled} onSelect={() => onSelect?.(item)}>
                      <span className="jui-command-search-icon">{item.icon ?? <ArrowRight size={16}/>}</span><span>{item.label}</span>{item.hint && <span className="jui-command-search-hint">{item.hint}</span>}
                    </Command.Item>)}
                  </Command.Group>)}
                </Command.List>
              </motion.div>
            </Command>
          </motion.div>
        </Dialog.Content>
      </motion.div>
    </Dialog.Portal>}</AnimatePresence>
  </Dialog.Root></MotionConfig></LayoutGroup>;
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
